    with open(filepath, "r", encoding="utf-8") as f:
        tree = ast.parse(f.read())

    lines = [f"## {module_name}"]

    for node in tree.body:
        # Modül düzeyinde sabitler (Assign)
        if isinstance(node, ast.Assign):
            if len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
                name = node.targets[0].id
                if not name.startswith('_'):
                    doc = get_docstring(node)
                    if doc: lines.append(f"- `{name}` — {doc}")

        # Modül düzeyinde fonksiyonlar/asenkron fonksiyonlar
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            if not node.name.startswith('_'):
                is_async = "async " if isinstance(node, ast.AsyncFunctionDef) else ""
                try:
                    args_part = ast.unparse(node.args)
                    sig = f"{is_async}{node.name}({args_part})"
                    if node.returns:
                        sig += f" -> {ast.unparse(node.returns)}"
                    doc = get_docstring(node)
                    lines.append(f"- `{sig}` — {doc}")
                except Exception as e:
                    pass

        # Sınıflar ve metotları
        elif isinstance(node, ast.ClassDef):
            if not node.name.startswith('_'):
                doc = get_docstring(node)
                lines.append(f"- `class {node.name}` — {doc}")
                for item in node.body:
                    if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)):
                        if not item.name.startswith('_') and item.name != "__init__":
                            is_async = "async " if isinstance(item, ast.AsyncFunctionDef) else ""
                            try:
                                args_part = ast.unparse(item.args)
                                sig = f"{is_async}{node.name}.{item.name}({args_part})"
                                if item.returns:
                                    sig += f" -> {ast.unparse(item.returns)}"
                                doc = get_docstring(item)
                                lines.append(f"- `{sig}` — {doc}")
                            except Exception as e:
                                pass

    return "\n".join(lines)

def main():
    package_dir = "paket"
    output_file = "API.md"
    all_content = []

    if not os.path.exists(package_dir):
        print(f"Hata: {package_dir} dizini bulunamadı.")
        return

    files = sorted([f for f in os.listdir(package_dir) if f.endswith(".py")])

    for filename in files:
        filepath = os.path.join(package_dir, filename)

        if filename == "__init__.py":
            if os.path.getsize(filepath) == 0:
                continue
            module_name = "paket"
        elif filename.startswith("_"):
            continue
        else:
            module_name = f"paket.{filename.replace('.py', '')}"

        content = process_file(filepath, module_name)
        if content and not content.startswith("## paket"): 
             all_content.append(content)
        elif content and len(content.split('\n')) > 1:
             all_content.append(content)

    with open(output_file, "w", encoding="utf-8") as f:
        f.write("\n\n".join(all_content))
    print("API.md başarıyla oluşturuldu.")

if __name__ == "__main__":
    main()
